//! Compiled-in MITRE ATT&CK names for OCSF findings (NAN-3224).
//!
//! `finding_info.attacks[]` carries tactic, technique and sub-technique names
//! and pairs each technique with its tactics. The finding emitter is pure: it
//! runs inside the shared detection transaction, and a replayed outbox row
//! must be byte-identical to the first one. Names therefore come from this
//! snapshot of the same pinned, SHA-256-verified bundle `sync.rs` loads into
//! PostgreSQL (`attack-v19.1-names.json`, regenerated by
//! `scripts/generate-mitre-attack-names.py`), never from the live catalog.

use std::collections::BTreeMap;
use std::sync::OnceLock;

#[derive(Debug, serde::Deserialize)]
struct Snapshot {
    tactics: BTreeMap<String, String>,
    techniques: BTreeMap<String, TechniqueEntry>,
}

#[derive(Debug, serde::Deserialize)]
struct TechniqueEntry {
    name: String,
    tactics: Vec<String>,
}

fn snapshot() -> &'static Snapshot {
    static SNAPSHOT: OnceLock<Snapshot> = OnceLock::new();
    SNAPSHOT.get_or_init(|| {
        serde_json::from_str(include_str!("attack-v19.1-names.json"))
            .expect("compiled-in ATT&CK name snapshot must be valid JSON")
    })
}

/// The ATT&CK name of a tactic (`TA0003` -> `Persistence`).
pub fn tactic_name(uid: &str) -> Option<&'static str> {
    snapshot().tactics.get(uid).map(String::as_str)
}

/// The ATT&CK name of a technique or sub-technique.
pub fn technique_name(uid: &str) -> Option<&'static str> {
    snapshot()
        .techniques
        .get(uid)
        .map(|entry| entry.name.as_str())
}

/// The tactics a technique or sub-technique belongs to (kill-chain phases).
pub fn technique_tactics(uid: &str) -> &'static [String] {
    snapshot()
        .techniques
        .get(uid)
        .map(|entry| entry.tactics.as_slice())
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snapshot_resolves_v19_names_and_tactics() {
        assert_eq!(tactic_name("TA0003"), Some("Persistence"));
        // v19 renamed Defense Evasion and split out Defense Impairment.
        assert_eq!(tactic_name("TA0005"), Some("Stealth"));
        assert!(tactic_name("TA0112").is_some());
        assert_eq!(
            technique_name("T1547.001"),
            Some("Registry Run Keys / Startup Folder")
        );
        assert_eq!(
            technique_name("T1547"),
            Some("Boot or Logon Autostart Execution")
        );
        assert!(technique_tactics("T1547.001").iter().any(|t| t == "TA0003"));
        assert_eq!(technique_name("T9999"), None);
        assert!(technique_tactics("T9999").is_empty());
        assert!(snapshot().techniques.len() >= 650);
    }
}
